const $ = id => document.getElementById(id);
const details = {
  damage: {title:'Hit DPS',value:'24.6',unit:'damage / second',formula:['18.45 average hit','×','1.333 casts / sec'],rows:[['Base fire damage','9–14'],['Increased spell damage','28%'],['Spell Damage and Mana','16%',true],['Spell Damage','12%',true],['More elemental damage','20%'],['Elemental Focus · level 1','×1.20',true],['Normal average hit after rounding','18'],['Critical chance / multiplier','5% / 150%'],['Average hit including criticals','18.45']],tags:['Gem source','2 passive nodes','PoB rounding']},
  life:{title:'Life',value:'285',unit:'maximum life',formula:['278 base life','+','7 from strength'],rows:[['Level / class','20 / Witch'],['Base life','278'],['Strength','14'],['Life from strength','7'],['Increased maximum life','0%'],['Final life','285']],tags:['Character level','Class attributes','No reservation modeled']},
  mana:{title:'Mana',value:'186',unit:'maximum mana',formula:['154 base mana','+','16 intelligence','+','16 passive'],rows:[['Base mana at level 20','154'],['Intelligence','32'],['Mana from intelligence','16'],['Spell Damage and Mana','+16'],['Final mana','186'],['Cost sustain','Pending']],tags:['Character level','Class attributes','Passive source']},
  armour:{title:'Armour',value:'23',unit:'armour rating',formula:['23 base armour','×','1.00 global scaling'],rows:[['Plate Vest base roll','23'],['Local modifiers','None'],['Global increased armour','0%'],['Final armour','23'],['Damage reduction','Depends on hit'],['Maximum hit / survivability','Pending']],tags:['Body armour','No quality','Local before global']},
  evasion:{title:'Evasion',value:'15',unit:'evasion rating',formula:['15 base evasion','×','1.02 from dexterity'],rows:[['Base evasion','15'],['Dexterity','14'],['Increased evasion from dexterity','2%'],['Before rounding','15.3'],['Final evasion','15'],['Evade chance','Needs enemy accuracy']],tags:['Base character stats','Attribute source','PoB rounding']}
};
function setDetail(key){const data=details[key];$('detail-title').textContent=data.title;const target=$('detail-content');target.replaceChildren();const total=document.createElement('div');total.className='calculation-total';const value=document.createElement('strong');value.textContent=data.value;const unit=document.createElement('span');unit.textContent=data.unit;total.append(value,unit);target.append(total);const formula=document.createElement('div');formula.className='formula';data.formula.forEach(part=>{const el=document.createElement(part==='×'||part==='+'?'span':'b');el.textContent=part;formula.append(el)});target.append(formula);const list=document.createElement('dl');list.className='breakdown';data.rows.forEach(([label,value,sub])=>{const row=document.createElement('div');if(sub)row.className='sub';const dt=document.createElement('dt');dt.textContent=label;const dd=document.createElement('dd');dd.textContent=value;row.append(dt,dd);list.append(row)});target.append(list);const tags=document.createElement('div');tags.className='source-tags';data.tags.forEach(tag=>{const span=document.createElement('span');span.textContent=tag;tags.append(span)});target.append(tags);document.querySelectorAll('[data-detail]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.detail===key)));$('announcement').textContent=`Showing ${data.title} breakdown.`}
document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>setDetail(button.dataset.detail)));
function setView(compare){$('overview').hidden=compare;$('comparison').hidden=!compare;$('overview-tab').setAttribute('aria-pressed',String(!compare));$('compare-tab').setAttribute('aria-pressed',String(compare));$('announcement').textContent=compare?'Equipment comparison concept. Candidate values are illustrative.':'Character overview concept.'}
$('overview-tab').addEventListener('click',()=>setView(false));$('compare-tab').addEventListener('click',()=>setView(true));
for(const [trigger,target] of [['config','config-dialog'],['resist-config','config-dialog'],['coverage','scope-dialog'],['settings','settings-dialog']]){$(trigger).addEventListener('click',()=>$(target).showModal())}
setDetail('damage');
